<style scoped lang="scss" src="./share-social-media-link.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";

/**
 * Renders a clickable bubble for a social media link for sharing. Use the
 * default slot for this component to place an Icon representing the social
 * media platform.
 */
@Component
export default class ShareSocialMediaLink extends Vue {
  /** This is the color of the bubble for the social media link */
  @Prop({ type: String }) color;
  /** Label displayed beneath the media link bubble */
  @Prop({ type: String }) label;

  get bubbleStyle() {
    return {
      background: this.color,
    };
  }

  handleClick() {
    /**
     * Emits a click event when any of this component is clicked.
     *
     * @event click
     */
    this.$emit("click");
  }
}
</script>

<template>
  <div class="ShareSocialMediaLink" @click="handleClick">
    <div class="ShareSocialMediaLink__Bubble" :style="bubbleStyle">
      <slot />
    </div>
    <div v-if="label" class="ShareSocialMediaLink__Label">{{ label }}</div>
  </div>
</template>
